INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fdd80893-3dbe-4942-9406-8e57190e9896', 'real_estate', NULL, 'What is a lien on a property?', '¿Qué es un gravamen sobre una propiedad?', '["A type of property tax", "A legal claim against a property used as collateral", "The property''s market value", "The property''s zoning classification"]', '["Un tipo de impuesto sobre la propiedad", "Un reclamo legal contra una propiedad utilizada como garantía", "El valor de mercado de la propiedad", "La clasificación de zonificación de la propiedad"]', 1, 'A lien is a legal right or interest that a creditor has in the debtor''s property, usually as security for a debt.', 'Un gravamen es un derecho legal o interés que un acreedor tiene en la propiedad del deudor, generalmente como garantía de una deuda.', true, '2026-01-14 18:28:35.320844', '2026-01-14 18:28:35.320844') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fe0076ea-7c18-4e14-9b0d-456ea7e26876', 'real_estate', NULL, 'What is equity in real estate?', '¿Qué es el patrimonio en bienes raíces?', '["The difference between the property value and the mortgage balance", "The monthly payment", "The interest rate", "The closing costs"]', '["La diferencia entre el valor de la propiedad y el saldo de la hipoteca", "El pago mensual", "La tasa de interés", "Los costos de cierre"]', 0, 'Equity is the portion of the property that the owner actually owns, calculated as market value minus outstanding loans.', 'El patrimonio es la porción de la propiedad que el propietario realmente posee, calculada como el valor de mercado menos los préstamos pendientes.', true, '2026-01-14 18:28:35.495615', '2026-01-14 18:28:35.495615') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('009e6257-fa4a-41be-af2b-e81795c2bd71', 'property_casualty', NULL, 'What is a fidelity bond?', '¿Qué es una fianza de fidelidad?', '["Coverage protecting against employee dishonesty", "A surety bond", "A bail bond", "A license bond"]', '["Cobertura que protege contra la deshonestidad de empleados", "Una fianza de garantía", "Una fianza de libertad", "Una fianza de licencia"]', 0, 'A fidelity bond protects employers from losses caused by dishonest acts of their employees.', 'Una fianza de fidelidad protege a los empleadores de pérdidas causadas por actos deshonestos de sus empleados.', true, '2026-01-14 22:46:59.742747', '2026-01-14 22:46:59.742747') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('00ea4305-55ad-45d4-8872-7bce57999ab0', 'property_casualty', NULL, 'What is rental reimbursement coverage?', '¿Qué es la cobertura de reembolso de alquiler?', '["Coverage for the cost of a rental car while your vehicle is being repaired", "Coverage for rental property", "Liability coverage", "Medical coverage"]', '["Cobertura para el costo de un auto de alquiler mientras su vehículo está siendo reparado", "Cobertura para propiedad de alquiler", "Cobertura de responsabilidad", "Cobertura médica"]', 0, 'Rental reimbursement coverage pays for a rental car while your vehicle is being repaired after a covered claim.', 'La cobertura de reembolso de alquiler paga por un auto de alquiler mientras su vehículo está siendo reparado después de un reclamo cubierto.', true, '2026-01-14 22:43:34.520272', '2026-01-14 22:43:34.520272') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('017c9e12-fe64-4c93-b149-38f6d36da0aa', 'property_casualty', NULL, 'What is collision coverage?', '¿Qué es la cobertura de colisión?', '["Coverage for damage to your vehicle from hitting another vehicle or object", "Coverage for damage from weather", "Coverage for theft", "Coverage for medical bills"]', '["Cobertura por daños a su vehículo por chocar con otro vehículo u objeto", "Cobertura por daños del clima", "Cobertura por robo", "Cobertura para facturas médicas"]', 0, 'Collision coverage pays to repair or replace your vehicle if it collides with another vehicle or object, regardless of fault.', 'La cobertura de colisión paga para reparar o reemplazar su vehículo si colisiona con otro vehículo u objeto, independientemente de la culpa.', true, '2026-01-14 22:43:34.49809', '2026-01-14 22:43:34.49809') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('01b46799-b17b-436c-b88c-959551a90a11', 'property_casualty', NULL, 'What is professional liability insurance (E&O)?', '¿Qué es el seguro de responsabilidad profesional (E&O)?', '["Coverage for claims arising from professional services or advice", "General liability insurance", "Property insurance", "Auto insurance"]', '["Cobertura para reclamos que surgen de servicios o consejos profesionales", "Seguro de responsabilidad general", "Seguro de propiedad", "Seguro de auto"]', 0, 'Professional liability (Errors & Omissions) insurance covers claims arising from professional negligence, errors, or omissions.', 'El seguro de responsabilidad profesional (Errores y Omisiones) cubre reclamos que surgen de negligencia profesional, errores u omisiones.', true, '2026-01-14 22:43:34.545248', '2026-01-14 22:43:34.545248') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('02a88d57-10bc-4fa6-a767-a1eb2a9f2dc0', 'property_casualty', NULL, 'What is commercial auto insurance?', '¿Qué es el seguro de auto comercial?', '["Auto insurance for vehicles used for business purposes", "Personal auto insurance", "Motorcycle insurance", "RV insurance"]', '["Seguro de auto para vehículos usados con fines comerciales", "Seguro de auto personal", "Seguro de motocicleta", "Seguro de RV"]', 0, 'Commercial auto insurance covers vehicles owned or used by a business for business purposes.', 'El seguro de auto comercial cubre vehículos propiedad de un negocio o usados por un negocio con fines comerciales.', true, '2026-01-14 22:43:34.553058', '2026-01-14 22:43:34.553058') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('037e0687-4253-458a-b396-69df98b369d8', 'property_casualty', NULL, 'What is Texas FAIR Plan?', '¿Qué es el Plan FAIR de Texas?', '["A state program providing property insurance for high-risk properties that can''t get coverage elsewhere", "A discount program", "A government subsidy", "A commercial insurance company"]', '["Un programa estatal que proporciona seguro de propiedad para propiedades de alto riesgo que no pueden obtener cobertura en otro lugar", "Un programa de descuento", "Un subsidio del gobierno", "Una compañía de seguros comercial"]', 0, 'The Texas FAIR Plan is a last-resort insurance program for property owners who cannot obtain coverage in the regular market.', 'El Plan FAIR de Texas es un programa de seguro de último recurso para propietarios que no pueden obtener cobertura en el mercado regular.', true, '2026-01-14 22:43:34.641161', '2026-01-14 22:43:34.641161') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('05b27548-f2e9-44e3-9f8d-5d097fa8ab80', 'property_casualty', NULL, 'What benefits does workers compensation typically provide?', '¿Qué beneficios proporciona típicamente la compensación de trabajadores?', '["Medical expenses, lost wages, rehabilitation, and death benefits", "Only medical expenses", "Only lost wages", "Only rehabilitation"]', '["Gastos médicos, salarios perdidos, rehabilitación y beneficios por muerte", "Solo gastos médicos", "Solo salarios perdidos", "Solo rehabilitación"]', 0, 'Workers compensation provides medical benefits, disability income, rehabilitation services, and death benefits to survivors.', 'La compensación de trabajadores proporciona beneficios médicos, ingresos por discapacidad, servicios de rehabilitación y beneficios por muerte a sobrevivientes.', true, '2026-01-14 22:49:00.512294', '2026-01-14 22:49:00.512294') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('07d0f908-8d05-46cd-983b-f448686fc0b0', 'property_casualty', NULL, 'What is subrogation?', '¿Qué es la subrogación?', '["The insurer''s right to recover payment from the party at fault", "A type of coverage", "A premium discount", "A policy endorsement"]', '["El derecho del asegurador de recuperar el pago de la parte culpable", "Un tipo de cobertura", "Un descuento de prima", "Un endoso de póliza"]', 0, 'Subrogation allows an insurance company to pursue a third party that caused an insurance loss to recover the amount paid to the policyholder.', 'La subrogación permite a una compañía de seguros perseguir a un tercero que causó una pérdida de seguro para recuperar la cantidad pagada al asegurado.', true, '2026-01-14 18:28:35.583271', '2026-01-14 18:28:35.583271') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('08594812-af75-4a0a-8bf0-3bbcbccf38c4', 'property_casualty', NULL, 'What is the cancellation notice period for a homeowners policy in Texas?', '¿Cuál es el período de aviso de cancelación para una póliza de propietarios en Texas?', '["30 days for most reasons, 10 days for non-payment", "7 days", "60 days", "90 days"]', '["30 días para la mayoría de razones, 10 días por falta de pago", "7 días", "60 días", "90 días"]', 0, 'Texas requires insurers to give 30 days'' notice for most cancellations and 10 days'' notice for non-payment of premium.', 'Texas requiere que los aseguradores den 30 días de aviso para la mayoría de cancelaciones y 10 días de aviso por falta de pago de prima.', true, '2026-01-14 22:43:34.662306', '2026-01-14 22:43:34.662306') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0ae5560a-6ede-437b-af2c-9a610a87f7d4', 'property_casualty', NULL, 'What is subrogation in insurance?', '¿Qué es la subrogación en seguros?', '["The insurer''s right to pursue a third party that caused the loss", "Transferring the policy to another person", "Canceling the policy", "Reducing the premium"]', '["El derecho del asegurador de perseguir a un tercero que causó la pérdida", "Transferir la póliza a otra persona", "Cancelar la póliza", "Reducir la prima"]', 0, 'Subrogation allows an insurer that paid a claim to pursue recovery from the third party responsible for causing the loss.', 'La subrogación permite a un asegurador que pagó un reclamo perseguir la recuperación del tercero responsable de causar la pérdida.', true, '2026-01-14 22:43:34.48828', '2026-01-14 22:43:34.48828') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0b40b44c-79dd-4abc-a357-3f4fdce25745', 'property_casualty', NULL, 'What is Personal Injury Protection (PIP) in Texas?', '¿Qué es la Protección de Lesiones Personales (PIP) en Texas?', '["No-fault coverage for medical expenses and lost wages for the insured", "Liability coverage", "Collision coverage", "Property damage coverage"]', '["Cobertura sin culpa para gastos médicos y salarios perdidos para el asegurado", "Cobertura de responsabilidad", "Cobertura de colisión", "Cobertura de daños a la propiedad"]', 0, 'PIP is no-fault coverage that pays medical expenses and lost income for you and your passengers, regardless of who caused the accident.', 'PIP es cobertura sin culpa que paga gastos médicos e ingresos perdidos para usted y sus pasajeros, independientemente de quién causó el accidente.', true, '2026-01-14 22:43:34.503354', '2026-01-14 22:43:34.503354') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0b820e00-027c-4b1d-b9a3-2b0c16ab9649', 'property_casualty', NULL, 'What is the parol evidence rule?', '¿Qué es la regla de evidencia parol?', '["Oral statements cannot change a written contract''s terms", "Oral statements always apply", "Written contracts are invalid", "Both oral and written are equal"]', '["Las declaraciones orales no pueden cambiar los términos de un contrato escrito", "Las declaraciones orales siempre aplican", "Los contratos escritos son inválidos", "Ambos oral y escrito son iguales"]', 0, 'The parol evidence rule prevents oral statements from modifying the terms of a written insurance contract.', 'La regla de evidencia parol previene que las declaraciones orales modifiquen los términos de un contrato de seguro escrito.', true, '2026-01-14 22:46:59.831662', '2026-01-14 22:46:59.831662') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0c3be785-6785-4c26-9c39-cf5ff03a2efb', 'property_casualty', NULL, 'What is a policy condition?', '¿Qué es una condición de póliza?', '["A provision that qualifies or limits the insurer''s obligation to pay", "The premium amount", "The coverage limit", "The deductible"]', '["Una disposición que califica o limita la obligación del asegurador de pagar", "El monto de la prima", "El límite de cobertura", "El deducible"]', 0, 'Policy conditions are provisions that qualify or limit the insurer''s promise to pay, often outlining duties of both parties.', 'Las condiciones de póliza son disposiciones que califican o limitan la promesa del asegurador de pagar, a menudo describiendo deberes de ambas partes.', true, '2026-01-14 22:43:34.592049', '2026-01-14 22:43:34.592049') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0c715da9-25d3-44a3-a4c2-8d153146c28c', 'property_casualty', NULL, 'What is estoppel in insurance?', '¿Qué es el estoppel en seguros?', '["Preventing a party from asserting a right because their actions led another to rely on different facts", "A coverage type", "A premium calculation", "A claim procedure"]', '["Prevenir que una parte afirme un derecho porque sus acciones llevaron a otro a confiar en hechos diferentes", "Un tipo de cobertura", "Un cálculo de prima", "Un procedimiento de reclamo"]', 0, 'Estoppel prevents an insurer from denying coverage when their actions caused the insured to reasonably rely on coverage.', 'El estoppel previene que un asegurador niegue cobertura cuando sus acciones causaron que el asegurado razonablemente confiara en la cobertura.', true, '2026-01-14 22:46:59.858077', '2026-01-14 22:46:59.858077') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0d6e0bd1-873e-4360-84c6-5e863aa092c9', 'property_casualty', NULL, 'Which peril is typically excluded from standard homeowners policies?', '¿Qué peligro típicamente se excluye de las pólizas estándar de propietarios?', '["Flood", "Fire", "Wind", "Lightning"]', '["Inundación", "Incendio", "Viento", "Rayo"]', 0, 'Flood damage is typically excluded from standard homeowners policies and requires separate flood insurance.', 'El daño por inundación típicamente se excluye de las pólizas estándar de propietarios y requiere seguro contra inundaciones separado.', true, '2026-01-14 22:43:34.472607', '2026-01-14 22:43:34.472607') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0ea4b7a4-8ce2-4bb9-a2de-54439889f38c', 'property_casualty', NULL, 'What is a contractor''s equipment floater?', '¿Qué es un flotante de equipo de contratista?', '["Coverage for mobile equipment used by contractors", "Building coverage", "Liability coverage", "Auto coverage"]', '["Cobertura para equipo móvil usado por contratistas", "Cobertura de edificio", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'A contractor''s equipment floater covers mobile equipment and tools used at various job sites.', 'Un flotante de equipo de contratista cubre equipo móvil y herramientas usados en varios sitios de trabajo.', true, '2026-01-14 22:46:59.751446', '2026-01-14 22:46:59.751446') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1260e1fd-410e-4aa3-bae1-f3c6ceadf1a3', 'property_casualty', NULL, 'What action can TDI take against an agent who commits fraud?', '¿Qué acción puede tomar TDI contra un agente que comete fraude?', '["Revoke or suspend the license and impose fines", "Only issue a warning", "Nothing", "Transfer to another state"]', '["Revocar o suspender la licencia e imponer multas", "Solo emitir una advertencia", "Nada", "Transferir a otro estado"]', 0, 'TDI can revoke, suspend, or refuse to renew licenses and impose administrative penalties for fraud.', 'TDI puede revocar, suspender o negarse a renovar licencias e imponer penalidades administrativas por fraude.', true, '2026-01-14 22:43:34.407126', '2026-01-14 22:43:34.407126') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('135e1f38-9e38-4bb7-bca1-b2d86bae9900', 'property_casualty', NULL, 'What is a moral hazard?', '¿Qué es un riesgo moral?', '["The tendency to be less careful when insured, or to intentionally cause a loss", "A physical condition that increases risk", "A type of coverage", "An insurance premium"]', '["La tendencia a ser menos cuidadoso cuando se está asegurado, o a causar una pérdida intencionalmente", "Una condición física que aumenta el riesgo", "Un tipo de cobertura", "Una prima de seguro"]', 0, 'Moral hazard refers to the increased likelihood of loss due to dishonesty or character defects of the insured.', 'El riesgo moral se refiere a la mayor probabilidad de pérdida debido a la deshonestidad o defectos de carácter del asegurado.', true, '2026-01-14 22:43:34.574701', '2026-01-14 22:43:34.574701') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('14a843ea-50fd-4bce-a85d-53f486871cac', 'property_casualty', NULL, 'What is environmental impairment liability insurance?', '¿Qué es el seguro de responsabilidad por deterioro ambiental?', '["Specialized coverage for pollution and environmental damage claims", "Standard liability", "Property coverage", "Auto coverage"]', '["Cobertura especializada para reclamos de contaminación y daño ambiental", "Responsabilidad estándar", "Cobertura de propiedad", "Cobertura de auto"]', 0, 'Environmental impairment liability insurance specifically covers pollution and environmental contamination claims.', 'El seguro de responsabilidad por deterioro ambiental cubre específicamente reclamos de contaminación y contaminación ambiental.', true, '2026-01-14 22:49:00.474571', '2026-01-14 22:49:00.474571') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('14aa78d7-8d74-4948-a771-00cb4760b4c1', 'property_casualty', NULL, 'What is the difference between actual cash value and replacement cost?', '¿Cuál es la diferencia entre valor real en efectivo y costo de reemplazo?', '["ACV deducts depreciation; replacement cost pays full replacement amount", "They are the same", "ACV is always higher", "Replacement cost includes depreciation"]', '["ACV deduce depreciación; costo de reemplazo paga el monto total de reemplazo", "Son lo mismo", "ACV siempre es más alto", "Costo de reemplazo incluye depreciación"]', 0, 'Actual Cash Value (ACV) is replacement cost minus depreciation, while replacement cost coverage pays to replace items without deducting for depreciation.', 'El Valor Real en Efectivo (ACV) es el costo de reemplazo menos depreciación, mientras que la cobertura de costo de reemplazo paga para reemplazar artículos sin deducir por depreciación.', true, '2026-01-14 18:28:35.571466', '2026-01-14 18:28:35.571466') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('15959a54-f237-428a-9ecd-cac9e04bdb81', 'property_casualty', NULL, 'What is rebating in insurance?', '¿Qué es el rebating en seguros?', '["Offering something of value not in the policy as an inducement to purchase", "Providing a policy discount", "Offering good customer service", "Providing a quote"]', '["Ofrecer algo de valor no incluido en la póliza como incentivo para comprar", "Proporcionar un descuento en la póliza", "Ofrecer buen servicio al cliente", "Proporcionar una cotización"]', 0, 'Rebating is the illegal practice of offering anything of value not specified in the policy as an inducement to purchase insurance.', 'El rebating es la práctica ilegal de ofrecer cualquier cosa de valor no especificada en la póliza como incentivo para comprar seguros.', true, '2026-01-14 22:43:34.416025', '2026-01-14 22:43:34.416025') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('16d945e1-d765-4bf3-8b92-a447401166ce', 'property_casualty', NULL, 'What is strict liability?', '¿Qué es la responsabilidad estricta?', '["Liability without proof of negligence, applied to abnormally dangerous activities", "Liability only with negligence", "No liability", "Criminal liability"]', '["Responsabilidad sin prueba de negligencia, aplicada a actividades anormalmente peligrosas", "Responsabilidad solo con negligencia", "Sin responsabilidad", "Responsabilidad criminal"]', 0, 'Strict liability holds a party responsible regardless of fault or negligence, often applied to inherently dangerous activities.', 'La responsabilidad estricta hace a una parte responsable independientemente de culpa o negligencia, a menudo aplicada a actividades inherentemente peligrosas.', true, '2026-01-14 22:46:59.605923', '2026-01-14 22:46:59.605923') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('179d42ee-f5c0-4948-834a-519356bd2b4d', 'property_casualty', NULL, 'What is a Business Owners Policy (BOP)?', '¿Qué es una Póliza de Propietarios de Negocios (BOP)?', '["A package policy for small to medium businesses combining property and liability", "A large corporation policy", "A personal policy", "An auto policy"]', '["Una póliza de paquete para pequeñas y medianas empresas que combina propiedad y responsabilidad", "Una póliza de corporación grande", "Una póliza personal", "Una póliza de auto"]', 0, 'A BOP is a simplified package policy designed for small to medium-sized businesses, combining property and general liability coverage.', 'Una BOP es una póliza de paquete simplificada diseñada para pequeñas y medianas empresas, combinando cobertura de propiedad y responsabilidad general.', true, '2026-01-14 22:43:34.537179', '2026-01-14 22:43:34.537179') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1896082b-33f0-48f4-bcc6-46401483b970', 'property_casualty', NULL, 'What is the business pursuits exclusion?', '¿Qué es la exclusión de actividades comerciales?', '["An exclusion in personal policies for liability arising from business activities", "Business coverage", "A coverage addition", "A premium discount"]', '["Una exclusión en pólizas personales por responsabilidad que surge de actividades comerciales", "Cobertura comercial", "Una adición de cobertura", "Un descuento de prima"]', 0, 'The business pursuits exclusion removes coverage for liability arising from the insured''s business activities.', 'La exclusión de actividades comerciales elimina cobertura por responsabilidad que surge de las actividades comerciales del asegurado.', true, '2026-01-14 22:49:00.484461', '2026-01-14 22:49:00.484461') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1a3d0400-6bc0-4644-a907-4af00d0b1f45', 'property_casualty', NULL, 'What is the difference between collision and comprehensive auto coverage?', '¿Cuál es la diferencia entre cobertura de colisión y comprensiva de auto?', '["Collision covers accidents; comprehensive covers non-collision events", "They are the same", "Collision covers theft", "Comprehensive covers accidents"]', '["Colisión cubre accidentes; comprensiva cubre eventos sin colisión", "Son lo mismo", "Colisión cubre robo", "Comprensiva cubre accidentes"]', 0, 'Collision covers damage from accidents with other vehicles or objects, while comprehensive covers theft, vandalism, weather damage, and animal strikes.', 'Colisión cubre daños de accidentes con otros vehículos u objetos, mientras que comprensiva cubre robo, vandalismo, daños climáticos e impactos con animales.', true, '2026-01-14 18:28:35.597536', '2026-01-14 18:28:35.597536') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1b180e0f-1b6c-4cbe-9e3f-15e5e19aff14', 'property_casualty', NULL, 'What is the difference between an agent and a broker?', '¿Cuál es la diferencia entre un agente y un corredor?', '["An agent represents the insurer; a broker represents the client", "They are the same", "A broker represents the insurer", "An agent represents the client"]', '["Un agente representa al asegurador; un corredor representa al cliente", "Son lo mismo", "Un corredor representa al asegurador", "Un agente representa al cliente"]', 0, 'An agent typically represents the insurance company, while a broker represents the insurance buyer.', 'Un agente típicamente representa a la compañía de seguros, mientras que un corredor representa al comprador de seguros.', true, '2026-01-14 22:43:34.654133', '2026-01-14 22:43:34.654133') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1b493cf1-1962-4362-9b57-32aaf4b4db90', 'property_casualty', NULL, 'What is an umbrella policy?', '¿Qué es una póliza paraguas?', '["Excess liability coverage beyond underlying policy limits", "Flood coverage", "Earthquake coverage", "Workers compensation"]', '["Cobertura de responsabilidad excedente más allá de los límites de la póliza subyacente", "Cobertura contra inundaciones", "Cobertura contra terremotos", "Compensación de trabajadores"]', 0, 'An umbrella policy provides additional liability coverage above the limits of homeowner''s, auto, and other primary policies.', 'Una póliza paraguas proporciona cobertura de responsabilidad adicional por encima de los límites de las pólizas primarias de propietario, auto y otras.', true, '2026-01-14 18:28:35.586897', '2026-01-14 18:28:35.586897') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1d13d7e4-fefa-41bf-946b-b28e2d6eb81e', 'property_casualty', NULL, 'What is valued policy law?', '¿Qué es la ley de póliza valorada?', '["A state law requiring insurers to pay the full face value for total loss of property", "A federal law", "A policy exclusion", "A coverage limitation"]', '["Una ley estatal que requiere que los aseguradores paguen el valor nominal total por pérdida total de propiedad", "Una ley federal", "Una exclusión de póliza", "Una limitación de cobertura"]', 0, 'Valued policy laws require insurers to pay the full policy face amount in case of a total loss.', 'Las leyes de póliza valorada requieren que los aseguradores paguen el monto nominal total de la póliza en caso de pérdida total.', true, '2026-01-14 22:46:59.668658', '2026-01-14 22:46:59.668658') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1e1e5a40-9c98-4353-a8a6-d9d5aab3157d', 'property_casualty', NULL, 'What is underinsured motorist coverage?', '¿Qué es la cobertura de motorista con seguro insuficiente?', '["Coverage when the at-fault driver''s insurance limits are insufficient to cover your damages", "Coverage for uninsured drivers", "Collision coverage", "Comprehensive coverage"]', '["Cobertura cuando los límites de seguro del conductor culpable son insuficientes para cubrir sus daños", "Cobertura para conductores sin seguro", "Cobertura de colisión", "Cobertura comprensiva"]', 0, 'Underinsured motorist coverage kicks in when the at-fault driver''s insurance isn''t enough to cover your injuries and damages.', 'La cobertura de motorista con seguro insuficiente entra cuando el seguro del conductor culpable no es suficiente para cubrir sus lesiones y daños.', true, '2026-01-14 22:43:34.510856', '2026-01-14 22:43:34.510856') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1f9f1d91-2eaf-41a3-9507-f596f2d4f488', 'property_casualty', NULL, 'What is the aircraft exclusion?', '¿Qué es la exclusión de aeronaves?', '["Exclusion for liability arising from aircraft ownership or operation", "Aircraft coverage", "A coverage addition", "A premium discount"]', '["Exclusión por responsabilidad que surge de la propiedad u operación de aeronaves", "Cobertura de aeronaves", "Una adición de cobertura", "Un descuento de prima"]', 0, 'The aircraft exclusion removes coverage for liability from owning, maintaining, or using aircraft.', 'La exclusión de aeronaves elimina cobertura por responsabilidad de poseer, mantener o usar aeronaves.', true, '2026-01-14 22:49:00.496628', '2026-01-14 22:49:00.496628') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('202efc08-a5fc-4170-8fee-84e50555d351', 'property_casualty', NULL, 'What state agency regulates insurance in Texas?', '¿Qué agencia estatal regula los seguros en Texas?', '["Texas Department of Insurance (TDI)", "Texas Real Estate Commission", "Texas Department of Licensing", "Texas Insurance Board"]', '["Departamento de Seguros de Texas (TDI)", "Comisión de Bienes Raíces de Texas", "Departamento de Licencias de Texas", "Junta de Seguros de Texas"]', 0, 'The Texas Department of Insurance (TDI) regulates the insurance industry in Texas.', 'El Departamento de Seguros de Texas (TDI) regula la industria de seguros en Texas.', true, '2026-01-14 22:43:34.378161', '2026-01-14 22:43:34.378161') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2789d76c-cdea-45cf-bc8a-25972f369588', 'property_casualty', NULL, 'What is the HO-3 policy form?', '¿Qué es el formulario de póliza HO-3?', '["The most common homeowners policy with open perils on dwelling, named perils on contents", "A renter''s policy", "A condo policy", "A mobile home policy"]', '["La póliza de propietarios más común con riesgos abiertos en vivienda, riesgos nombrados en contenidos", "Una póliza de inquilinos", "Una póliza de condominio", "Una póliza de casa móvil"]', 0, 'The HO-3 is the most common homeowners policy, providing open peril coverage on the dwelling and named peril coverage on personal property.', 'El HO-3 es la póliza de propietarios más común, proporcionando cobertura de riesgo abierto en la vivienda y cobertura de riesgo nombrado en propiedad personal.', true, '2026-01-14 22:43:34.443098', '2026-01-14 22:43:34.443098') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2802dcff-16cf-4c77-a6a8-7129ea54d02a', 'property_casualty', NULL, 'What is the duties after loss condition?', '¿Qué es la condición de deberes después de la pérdida?', '["Requirements the insured must fulfill after a loss occurs", "Pre-loss requirements", "Coverage limits", "Premium calculations"]', '["Requisitos que el asegurado debe cumplir después de que ocurra una pérdida", "Requisitos previos a la pérdida", "Límites de cobertura", "Cálculos de prima"]', 0, 'Duties after loss require the insured to take specific actions after a loss, like protecting property and cooperating with the investigation.', 'Los deberes después de la pérdida requieren que el asegurado tome acciones específicas después de una pérdida, como proteger la propiedad y cooperar con la investigación.', true, '2026-01-14 22:46:59.697029', '2026-01-14 22:46:59.697029') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('29f4f853-58e7-4135-9297-856665f92951', 'property_casualty', NULL, 'What is liability coverage in auto insurance?', '¿Qué es la cobertura de responsabilidad en el seguro de auto?', '["Coverage for damages you cause to others", "Coverage for your own vehicle", "Coverage for medical bills", "Coverage for theft"]', '["Cobertura por daños que usted causa a otros", "Cobertura para su propio vehículo", "Cobertura para facturas médicas", "Cobertura por robo"]', 0, 'Liability coverage pays for injuries and property damage you cause to others in an accident where you are at fault.', 'La cobertura de responsabilidad paga por lesiones y daños a la propiedad que usted causa a otros en un accidente donde usted tiene la culpa.', true, '2026-01-14 22:43:34.494183', '2026-01-14 22:43:34.494183') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2b424ee3-f693-411a-aee5-07dfd0481766', 'property_casualty', NULL, 'What is debris removal coverage?', '¿Qué es la cobertura de remoción de escombros?', '["Coverage for costs to remove debris after a covered loss", "Coverage for trash removal", "Liability coverage", "Auto coverage"]', '["Cobertura para costos de remover escombros después de una pérdida cubierta", "Cobertura para remoción de basura", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Debris removal coverage pays for the cost of removing debris from a property after a covered loss.', 'La cobertura de remoción de escombros paga el costo de remover escombros de una propiedad después de una pérdida cubierta.', true, '2026-01-14 22:46:59.642374', '2026-01-14 22:46:59.642374') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2d78f9e1-f961-4d13-ab48-424f79e597b8', 'property_casualty', NULL, 'What is workers'' compensation insurance?', '¿Qué es el seguro de compensación de trabajadores?', '["Coverage for employee injuries and illnesses arising from employment", "Health insurance for employees", "Life insurance for workers", "Disability insurance"]', '["Cobertura para lesiones y enfermedades de empleados que surgen del empleo", "Seguro de salud para empleados", "Seguro de vida para trabajadores", "Seguro de discapacidad"]', 0, 'Workers'' compensation provides benefits to employees who suffer work-related injuries or illnesses, covering medical costs and lost wages.', 'La compensación de trabajadores proporciona beneficios a empleados que sufren lesiones o enfermedades relacionadas con el trabajo, cubriendo costos médicos y salarios perdidos.', true, '2026-01-14 22:43:34.547452', '2026-01-14 22:43:34.547452') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('303a6104-f7ac-4269-a74a-ce0198866f7a', 'property_casualty', NULL, 'What happens if you let an uninsured friend drive your car and they cause an accident?', '¿Qué pasa si deja que un amigo sin seguro conduzca su auto y causa un accidente?', '["Your insurance typically covers the accident as primary", "The friend''s insurance covers it", "No coverage applies", "The state pays for damages"]', '["Su seguro típicamente cubre el accidente como primario", "El seguro del amigo lo cubre", "No aplica cobertura", "El estado paga por los daños"]', 0, 'In most cases, auto insurance follows the vehicle, so your policy would be primary coverage for permissive users.', 'En la mayoría de los casos, el seguro de auto sigue al vehículo, así que su póliza sería la cobertura primaria para usuarios permitidos.', true, '2026-01-14 22:43:34.531284', '2026-01-14 22:43:34.531284') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('30880f9f-ae35-42ee-b41e-725f02009407', 'property_casualty', NULL, 'What is the Texas Windstorm Insurance Association (TWIA)?', '¿Qué es la Asociación de Seguros contra Tormentas de Viento de Texas (TWIA)?', '["An insurance pool providing wind and hail coverage for coastal areas", "A flood insurance program", "A life insurance company", "A health insurance provider"]', '["Un grupo de seguros que proporciona cobertura de viento y granizo para áreas costeras", "Un programa de seguro contra inundaciones", "Una compañía de seguro de vida", "Un proveedor de seguro de salud"]', 0, 'TWIA provides wind and hail coverage to property owners in designated Texas coastal counties who cannot obtain coverage elsewhere.', 'TWIA proporciona cobertura de viento y granizo a propietarios en condados costeros designados de Texas que no pueden obtener cobertura en otro lugar.', true, '2026-01-14 18:28:35.627389', '2026-01-14 18:28:35.627389') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3417456f-21a9-45dc-9d6b-b5ef91a9e64e', 'property_casualty', NULL, 'What is uninsured motorist coverage?', '¿Qué es la cobertura de motorista sin seguro?', '["Coverage when you''re hit by a driver who has no insurance", "Coverage for your vehicle repairs", "Medical payments coverage", "Comprehensive coverage"]', '["Cobertura cuando es golpeado por un conductor que no tiene seguro", "Cobertura para reparaciones de su vehículo", "Cobertura de pagos médicos", "Cobertura comprensiva"]', 0, 'Uninsured motorist coverage protects you when you''re injured by a driver who has no liability insurance.', 'La cobertura de motorista sin seguro lo protege cuando es lesionado por un conductor que no tiene seguro de responsabilidad.', true, '2026-01-14 22:43:34.506941', '2026-01-14 22:43:34.506941') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('34be9bde-9d8a-4b2b-b4f3-8a15db04e13d', 'property_casualty', NULL, 'What is a deductible?', '¿Qué es un deducible?', '["The amount the insured pays before insurance covers the rest", "The premium amount", "The coverage limit", "The policy term"]', '["La cantidad que el asegurado paga antes de que el seguro cubra el resto", "El monto de la prima", "El límite de cobertura", "El plazo de la póliza"]', 0, 'A deductible is the amount a policyholder must pay out-of-pocket before the insurance company pays for a covered loss.', 'Un deducible es la cantidad que un asegurado debe pagar de su bolsillo antes de que la compañía de seguros pague por una pérdida cubierta.', true, '2026-01-14 18:28:35.567556', '2026-01-14 18:28:35.567556') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('35252c8d-2ec3-47ad-ae88-d05b4b7e585d', 'property_casualty', NULL, 'What is the principle of indemnity?', '¿Cuál es el principio de indemnización?', '["Insurance should restore the insured to the same financial position as before the loss", "Insurance should profit the insured", "Insurance covers all losses", "Insurance is optional"]', '["El seguro debe restaurar al asegurado a la misma posición financiera que antes de la pérdida", "El seguro debe beneficiar al asegurado", "El seguro cubre todas las pérdidas", "El seguro es opcional"]', 0, 'The principle of indemnity ensures that insurance restores the insured to their pre-loss condition without profit.', 'El principio de indemnización asegura que el seguro restaure al asegurado a su condición anterior a la pérdida sin ganancia.', true, '2026-01-14 22:43:34.565388', '2026-01-14 22:43:34.565388') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('379f3c68-120a-4e2e-9543-551d988488fc', 'property_casualty', NULL, 'What is experience modification in workers compensation?', '¿Qué es la modificación de experiencia en compensación de trabajadores?', '["A factor that adjusts premium based on the employer''s loss history", "A coverage type", "A claim procedure", "A policy endorsement"]', '["Un factor que ajusta la prima basándose en el historial de pérdidas del empleador", "Un tipo de cobertura", "Un procedimiento de reclamo", "Un endoso de póliza"]', 0, 'Experience modification adjusts workers comp premiums based on the employer''s actual loss experience compared to average.', 'La modificación de experiencia ajusta las primas de compensación de trabajadores basándose en la experiencia de pérdidas real del empleador comparada con el promedio.', true, '2026-01-14 22:49:00.50574', '2026-01-14 22:49:00.50574') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('37fba652-c390-412c-bb4a-64bf33d65544', 'property_casualty', NULL, 'What is the good student discount in auto insurance?', '¿Qué es el descuento de buen estudiante en seguro de auto?', '["A discount for students who maintain good grades", "A discount for safe drivers", "A discount for new cars", "A discount for seniors"]', '["Un descuento para estudiantes que mantienen buenas calificaciones", "Un descuento para conductores seguros", "Un descuento para carros nuevos", "Un descuento para adultos mayores"]', 0, 'The good student discount reduces auto premiums for young drivers who maintain good academic grades.', 'El descuento de buen estudiante reduce las primas de auto para conductores jóvenes que mantienen buenas calificaciones académicas.', true, '2026-01-14 22:49:00.5367', '2026-01-14 22:49:00.5367') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('39154463-a4d6-492e-a884-ab50e082d6c4', 'property_casualty', NULL, 'What is products liability coverage?', '¿Qué es la cobertura de responsabilidad de productos?', '["Coverage for claims arising from products manufactured or sold by the business", "Coverage for product warranties", "Property insurance", "Auto insurance"]', '["Cobertura para reclamos que surgen de productos fabricados o vendidos por el negocio", "Cobertura para garantías de productos", "Seguro de propiedad", "Seguro de auto"]', 0, 'Products liability coverage protects businesses against claims for injuries or damages caused by products they manufacture or sell.', 'La cobertura de responsabilidad de productos protege a los negocios contra reclamos por lesiones o daños causados por productos que fabrican o venden.', true, '2026-01-14 22:43:34.542563', '2026-01-14 22:43:34.542563') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('39bb345f-5fd8-4479-b3da-e484063affec', 'property_casualty', NULL, 'What is the difference between named perils and open perils coverage?', '¿Cuál es la diferencia entre cobertura de riesgos nombrados y riesgos abiertos?', '["Named perils covers only listed perils; open perils covers all except exclusions", "They are the same", "Open perils is cheaper", "Named perils covers more"]', '["Riesgos nombrados cubre solo riesgos listados; riesgos abiertos cubre todos excepto exclusiones", "Son lo mismo", "Riesgos abiertos es más barato", "Riesgos nombrados cubre más"]', 0, 'Named perils coverage only covers losses from specifically listed causes, while open perils covers any cause not specifically excluded.', 'La cobertura de riesgos nombrados solo cubre pérdidas de causas específicamente listadas, mientras que riesgos abiertos cubre cualquier causa no específicamente excluida.', true, '2026-01-14 22:43:34.42414', '2026-01-14 22:43:34.42414') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3bee314f-ba0d-4f63-837a-5aea4ffad070', 'property_casualty', NULL, 'What is twisting in insurance?', '¿Qué es el twisting en seguros?', '["Using misrepresentation to induce a policyholder to replace existing coverage", "Selling multiple policies", "Offering discounts", "Providing good service"]', '["Usar tergiversación para inducir a un asegurado a reemplazar cobertura existente", "Vender múltiples pólizas", "Ofrecer descuentos", "Proporcionar buen servicio"]', 0, 'Twisting is the unethical practice of using misrepresentation to induce a customer to cancel existing coverage and buy a new policy.', 'El twisting es la práctica poco ética de usar tergiversación para inducir a un cliente a cancelar cobertura existente y comprar una nueva póliza.', true, '2026-01-14 22:43:34.411199', '2026-01-14 22:43:34.411199') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3ca05689-c2a0-4e14-96b4-2bd6f96be4e5', 'property_casualty', NULL, 'What is towing and labor coverage?', '¿Qué es la cobertura de remolque y mano de obra?', '["Coverage for towing and roadside service costs", "Collision coverage", "Comprehensive coverage", "Liability coverage"]', '["Cobertura para costos de remolque y servicio en carretera", "Cobertura de colisión", "Cobertura comprensiva", "Cobertura de responsabilidad"]', 0, 'Towing and labor coverage pays for towing and minor roadside repairs when your vehicle is disabled.', 'La cobertura de remolque y mano de obra paga por remolque y reparaciones menores en carretera cuando su vehículo está deshabilitado.', true, '2026-01-14 22:43:34.522487', '2026-01-14 22:43:34.522487') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3cda1974-283b-414f-9870-a7056b5133e8', 'property_casualty', NULL, 'What is a hazard in insurance?', '¿Qué es un riesgo en seguros?', '["A condition that increases the likelihood or severity of a loss", "The cause of a loss", "A type of coverage", "A premium discount"]', '["Una condición que aumenta la probabilidad o severidad de una pérdida", "La causa de una pérdida", "Un tipo de cobertura", "Un descuento de prima"]', 0, 'A hazard is a condition that increases the probability or severity of a loss from a given peril.', 'Un riesgo es una condición que aumenta la probabilidad o severidad de una pérdida de un peligro dado.', true, '2026-01-14 22:43:34.667704', '2026-01-14 22:43:34.667704') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3d99ce30-1208-4543-9273-9fc087943a66', 'property_casualty', NULL, 'What is the Texas Automobile Insurance Plan Association (TAIPA)?', '¿Qué es la Asociación del Plan de Seguro de Automóviles de Texas (TAIPA)?', '["An assigned risk plan for drivers who can''t get auto insurance in the regular market", "A discount program", "A federal program", "A private company"]', '["Un plan de riesgo asignado para conductores que no pueden obtener seguro de auto en el mercado regular", "Un programa de descuento", "Un programa federal", "Una compañía privada"]', 0, 'TAIPA is Texas''s assigned risk plan, providing auto insurance to drivers who cannot obtain coverage elsewhere.', 'TAIPA es el plan de riesgo asignado de Texas, proporcionando seguro de auto a conductores que no pueden obtener cobertura en otro lugar.', true, '2026-01-14 22:43:34.658904', '2026-01-14 22:43:34.658904') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3da59830-0095-4665-865d-a81f91008d4d', 'property_casualty', NULL, 'What is builders risk insurance?', '¿Qué es el seguro de riesgo de constructores?', '["Coverage for buildings under construction", "Completed building coverage", "Liability coverage", "Auto coverage"]', '["Cobertura para edificios en construcción", "Cobertura de edificio completado", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Builders risk insurance covers buildings and materials during construction until the project is complete.', 'El seguro de riesgo de constructores cubre edificios y materiales durante la construcción hasta que el proyecto esté completo.', true, '2026-01-14 22:46:59.748442', '2026-01-14 22:46:59.748442') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3eed9b25-5cf8-46cf-9d73-b6c1dbea5631', 'property_casualty', NULL, 'What is agreed value coverage?', '¿Qué es la cobertura de valor acordado?', '["Coverage where insurer and insured agree on the value upfront, eliminating coinsurance", "Actual cash value coverage", "Market value coverage", "Replacement cost coverage"]', '["Cobertura donde asegurador y asegurado acuerdan el valor por adelantado, eliminando coaseguro", "Cobertura de valor real en efectivo", "Cobertura de valor de mercado", "Cobertura de costo de reemplazo"]', 0, 'Agreed value coverage establishes an agreed-upon value for the property, waiving the coinsurance requirement.', 'La cobertura de valor acordado establece un valor acordado para la propiedad, renunciando al requisito de coaseguro.', true, '2026-01-14 22:46:59.648762', '2026-01-14 22:46:59.648762') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3f3b0927-9109-46c8-83c3-b80cd5e4032b', 'property_casualty', NULL, 'How many hours of pre-licensing education are required for a Property & Casualty license in Texas?', '¿Cuántas horas de educación previa a la licencia se requieren para una licencia de Propiedad y Accidentes en Texas?', '["40 hours", "20 hours", "60 hours", "80 hours"]', '["40 horas", "20 horas", "60 horas", "80 horas"]', 0, 'Texas requires 40 hours of pre-licensing education for a Property & Casualty insurance license.', 'Texas requiere 40 horas de educación previa a la licencia para una licencia de seguros de Propiedad y Accidentes.', true, '2026-01-14 22:43:34.386451', '2026-01-14 22:43:34.386451') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3f3b613a-fb5d-4507-b3b2-2f429fb7cd1b', 'property_casualty', NULL, 'What is the purpose of a policy limit?', '¿Cuál es el propósito de un límite de póliza?', '["To cap the maximum amount the insurer will pay for a covered loss", "To set the premium", "To define deductibles", "To list exclusions"]', '["Limitar la cantidad máxima que el asegurador pagará por una pérdida cubierta", "Establecer la prima", "Definir deducibles", "Listar exclusiones"]', 0, 'Policy limits establish the maximum amount the insurance company will pay for covered losses.', 'Los límites de póliza establecen la cantidad máxima que la compañía de seguros pagará por pérdidas cubiertas.', true, '2026-01-14 22:49:00.525055', '2026-01-14 22:49:00.525055') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3f4e9293-eef5-4718-b783-5da07bdd832c', 'property_casualty', NULL, 'What does a homeowner''s insurance policy typically cover?', '¿Qué cubre típicamente una póliza de seguro de propietario de vivienda?', '["Only the structure of the home", "The structure, personal property, liability, and additional living expenses", "Only personal belongings", "Only liability claims"]', '["Solo la estructura de la casa", "La estructura, propiedad personal, responsabilidad y gastos de vida adicionales", "Solo pertenencias personales", "Solo reclamaciones de responsabilidad"]', 1, 'A standard homeowner''s policy provides comprehensive coverage including the dwelling, personal property, liability protection, and additional living expenses if the home becomes uninhabitable.', 'Una póliza de propietario estándar proporciona cobertura integral que incluye la vivienda, propiedad personal, protección de responsabilidad y gastos de vida adicionales si la casa se vuelve inhabitable.', true, '2026-01-14 16:50:01.892074', '2026-01-14 16:50:01.892074') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('41b24e9a-5b09-438b-8821-4c918126d1a3', 'property_casualty', NULL, 'What is the declarations page?', '¿Qué es la página de declaraciones?', '["The section of a policy that includes specific information about the insured and coverage", "The claims form", "The payment receipt", "The application"]', '["La sección de una póliza que incluye información específica sobre el asegurado y la cobertura", "El formulario de reclamos", "El recibo de pago", "La solicitud"]', 0, 'The declarations page summarizes key policy information: named insured, policy period, limits, premiums, and covered property.', 'La página de declaraciones resume información clave de la póliza: asegurado nombrado, período de la póliza, límites, primas y propiedad cubierta.', true, '2026-01-14 22:43:34.597678', '2026-01-14 22:43:34.597678') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('43e80a97-5880-41ed-ba86-1c2479d0ecb9', 'property_casualty', NULL, 'What is a scheduled personal property endorsement?', '¿Qué es un endoso de propiedad personal programada?', '["An endorsement listing specific high-value items for additional coverage", "A policy cancellation", "A premium reduction", "A claim form"]', '["Un endoso que lista artículos específicos de alto valor para cobertura adicional", "Una cancelación de póliza", "Una reducción de prima", "Un formulario de reclamo"]', 0, 'A scheduled personal property endorsement adds specific coverage for high-value items like jewelry, art, or collectibles.', 'Un endoso de propiedad personal programada agrega cobertura específica para artículos de alto valor como joyas, arte o coleccionables.', true, '2026-01-14 22:43:34.645868', '2026-01-14 22:43:34.645868') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4638b5ea-1c4a-4dae-b5a0-874d859e1e49', 'property_casualty', NULL, 'What is a public adjuster?', '¿Qué es un ajustador público?', '["An adjuster hired by the insured to represent their interests in a claim", "An adjuster employed by the insurance company", "A government employee", "An independent contractor for insurers"]', '["Un ajustador contratado por el asegurado para representar sus intereses en un reclamo", "Un ajustador empleado por la compañía de seguros", "Un empleado del gobierno", "Un contratista independiente para aseguradores"]', 0, 'A public adjuster works for the policyholder, not the insurance company, to help negotiate and settle claims.', 'Un ajustador público trabaja para el asegurado, no la compañía de seguros, para ayudar a negociar y liquidar reclamos.', true, '2026-01-14 22:43:34.611031', '2026-01-14 22:43:34.611031') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('469c1539-bdcb-4563-859c-f2b1cc53bca6', 'property_casualty', NULL, 'What is ordinance or law coverage?', '¿Qué es la cobertura de ordenanza o ley?', '["Coverage for additional costs to comply with building codes when repairing or rebuilding", "Standard property coverage", "Liability coverage", "Auto coverage"]', '["Cobertura para costos adicionales de cumplir con códigos de construcción al reparar o reconstruir", "Cobertura estándar de propiedad", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Ordinance or law coverage pays for additional costs to bring a damaged building up to current building codes.', 'La cobertura de ordenanza o ley paga costos adicionales para llevar un edificio dañado a los códigos de construcción actuales.', true, '2026-01-14 22:46:59.638097', '2026-01-14 22:46:59.638097') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('47009666-7eeb-441e-a5dd-fb49fb7cd0a5', 'property_casualty', NULL, 'What is a policy endorsement?', '¿Qué es un endoso de póliza?', '["A written document that modifies the original policy terms", "A signature on the policy", "The policy declaration", "The premium payment"]', '["Un documento escrito que modifica los términos originales de la póliza", "Una firma en la póliza", "La declaración de la póliza", "El pago de la prima"]', 0, 'An endorsement (or rider) is a written document attached to a policy that modifies its terms and conditions.', 'Un endoso (o anexo) es un documento escrito adjunto a una póliza que modifica sus términos y condiciones.', true, '2026-01-14 22:43:34.594469', '2026-01-14 22:43:34.594469') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('47ac72df-a67e-4534-a43d-ebfff5fda534', 'property_casualty', NULL, 'What is pair and set coverage?', '¿Qué es la cobertura de par y conjunto?', '["Provision for how to value loss when only part of a pair or set is damaged", "Coverage for matching items", "Full replacement coverage", "Liability coverage"]', '["Disposición para cómo valorar pérdida cuando solo parte de un par o conjunto está dañado", "Cobertura para artículos que hacen juego", "Cobertura de reemplazo total", "Cobertura de responsabilidad"]', 0, 'Pair and set clauses determine how the insurer will value a loss when only one item of a pair or set is damaged.', 'Las cláusulas de par y conjunto determinan cómo el asegurador valorará una pérdida cuando solo un artículo de un par o conjunto está dañado.', true, '2026-01-14 22:46:59.675099', '2026-01-14 22:46:59.675099') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4b669792-e8b0-43cf-8261-5cabd44cdbca', 'property_casualty', NULL, 'What is comparative negligence?', '¿Qué es la negligencia comparativa?', '["A system where damages are reduced by the plaintiff''s percentage of fault", "Full responsibility for the defendant", "No responsibility for either party", "Automatic claim denial"]', '["Un sistema donde los daños se reducen por el porcentaje de culpa del demandante", "Responsabilidad total del demandado", "Sin responsabilidad para ninguna parte", "Denegación automática de reclamo"]', 0, 'Comparative negligence reduces the plaintiff''s recovery by their percentage of fault in causing the accident.', 'La negligencia comparativa reduce la recuperación del demandante por su porcentaje de culpa en causar el accidente.', true, '2026-01-14 22:43:34.681782', '2026-01-14 22:43:34.681782') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4bb99428-0860-4f91-ae2f-c3a9ec96649f', 'property_casualty', NULL, 'What does Coverage C in a homeowners policy cover?', '¿Qué cubre la Cobertura C en una póliza de propietarios?', '["Personal property (belongings)", "The dwelling", "Other structures", "Liability"]', '["Propiedad personal (pertenencias)", "La vivienda", "Otras estructuras", "Responsabilidad"]', 0, 'Coverage C covers the policyholder''s personal property, including furniture, clothing, electronics, and other belongings.', 'La Cobertura C cubre la propiedad personal del asegurado, incluyendo muebles, ropa, electrónicos y otras pertenencias.', true, '2026-01-14 22:43:34.453079', '2026-01-14 22:43:34.453079') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4ec55b52-9122-42fd-9b5f-886d4c254d4b', 'property_casualty', NULL, 'What is farm insurance?', '¿Qué es el seguro agrícola?', '["Coverage for farm dwellings, equipment, livestock, and farm liability", "Homeowners only", "Commercial only", "Auto only"]', '["Cobertura para viviendas agrícolas, equipo, ganado y responsabilidad agrícola", "Solo propietarios", "Solo comercial", "Solo auto"]', 0, 'Farm insurance combines residential coverage with coverage for farm equipment, livestock, and farm operations.', 'El seguro agrícola combina cobertura residencial con cobertura para equipo agrícola, ganado y operaciones agrícolas.', true, '2026-01-14 22:46:59.783875', '2026-01-14 22:46:59.783875') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4fb8a248-13e6-44e4-8f10-8cfe052a73ad', 'property_casualty', NULL, 'What is the appraisal clause?', '¿Qué es la cláusula de tasación?', '["A policy provision for resolving disputes about the value of a loss", "A coverage limit", "A premium calculation", "A policy exclusion"]', '["Una disposición de póliza para resolver disputas sobre el valor de una pérdida", "Un límite de cobertura", "Un cálculo de prima", "Una exclusión de póliza"]', 0, 'The appraisal clause allows either party to demand an appraisal when they disagree about the amount of a loss.', 'La cláusula de tasación permite a cualquier parte exigir una tasación cuando no están de acuerdo sobre el monto de una pérdida.', true, '2026-01-14 22:43:34.624875', '2026-01-14 22:43:34.624875') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('529254ff-71a9-4132-8b98-afbcf4ff7576', 'property_casualty', NULL, 'What is an umbrella policy?', '¿Qué es una póliza paraguas?', '["Excess liability coverage that provides additional limits above underlying policies", "Weather coverage", "A homeowners policy", "An auto policy"]', '["Cobertura de responsabilidad excedente que proporciona límites adicionales por encima de las pólizas subyacentes", "Cobertura climática", "Una póliza de propietarios", "Una póliza de auto"]', 0, 'An umbrella policy provides excess liability coverage above the limits of underlying auto, home, or other liability policies.', 'Una póliza paraguas proporciona cobertura de responsabilidad excedente por encima de los límites de las pólizas subyacentes de auto, hogar u otra responsabilidad.', true, '2026-01-14 22:43:34.555597', '2026-01-14 22:43:34.555597') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('54c00c91-3352-42fa-b715-fc7bbf985298', 'property_casualty', NULL, 'What is the attractive nuisance doctrine?', '¿Qué es la doctrina de atractivo peligroso?', '["Property owners may be liable for injuries to children attracted to dangerous conditions on their property", "A type of policy", "A coverage exclusion", "A premium discount"]', '["Los propietarios pueden ser responsables por lesiones a niños atraídos a condiciones peligrosas en su propiedad", "Un tipo de póliza", "Una exclusión de cobertura", "Un descuento de prima"]', 0, 'The attractive nuisance doctrine holds property owners liable for injuries to children attracted by dangerous conditions like pools.', 'La doctrina de atractivo peligroso hace a los propietarios responsables por lesiones a niños atraídos por condiciones peligrosas como piscinas.', true, '2026-01-14 22:46:59.630294', '2026-01-14 22:46:59.630294') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('55f1a1ee-af40-47fe-8cf3-454ccae8e53a', 'property_casualty', NULL, 'What is the motor vehicle exclusion in homeowners policies?', '¿Qué es la exclusión de vehículo motorizado en pólizas de propietarios?', '["Exclusion for liability arising from motor vehicle use", "Coverage for motor vehicles", "A premium discount", "A coverage addition"]', '["Exclusión por responsabilidad que surge del uso de vehículos motorizados", "Cobertura para vehículos motorizados", "Un descuento de prima", "Una adición de cobertura"]', 0, 'The motor vehicle exclusion removes coverage for motor vehicle-related liability from homeowners policies.', 'La exclusión de vehículo motorizado elimina cobertura por responsabilidad relacionada con vehículos motorizados de las pólizas de propietarios.', true, '2026-01-14 22:49:00.489153', '2026-01-14 22:49:00.489153') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('56d55f5c-40fd-4456-b34d-2a56ab8c90af', 'property_casualty', NULL, 'What is adverse selection?', '¿Qué es la selección adversa?', '["The tendency of higher-risk individuals to seek more insurance", "Choosing the best policy", "A coverage type", "An underwriting term"]', '["La tendencia de individuos de mayor riesgo a buscar más seguro", "Elegir la mejor póliza", "Un tipo de cobertura", "Un término de suscripción"]', 0, 'Adverse selection occurs when those most likely to have a loss are the most likely to purchase insurance.', 'La selección adversa ocurre cuando aquellos más propensos a tener una pérdida son los más propensos a comprar seguros.', true, '2026-01-14 22:43:34.586749', '2026-01-14 22:43:34.586749') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('56e861f3-6c54-465d-9bd7-aba32a507939', 'property_casualty', NULL, 'What is a loss ratio?', '¿Qué es un índice de pérdida?', '["The ratio of claims paid to premiums earned", "The deductible amount", "The coverage limit", "The premium cost"]', '["La proporción de reclamos pagados a primas ganadas", "El monto del deducible", "El límite de cobertura", "El costo de la prima"]', 0, 'Loss ratio is calculated by dividing incurred losses by earned premiums, used to measure insurer profitability.', 'El índice de pérdida se calcula dividiendo las pérdidas incurridas por las primas ganadas, usado para medir la rentabilidad del asegurador.', true, '2026-01-14 22:43:34.632384', '2026-01-14 22:43:34.632384') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('56edbe18-336e-425d-80d6-144da4b014cf', 'property_casualty', NULL, 'What does Coverage F in a homeowners policy cover?', '¿Qué cubre la Cobertura F en una póliza de propietarios?', '["Medical payments to others", "The dwelling", "Personal property", "Liability lawsuits"]', '["Pagos médicos a otros", "La vivienda", "Propiedad personal", "Demandas de responsabilidad"]', 0, 'Coverage F provides medical payments to others who are injured on the insured''s property, regardless of fault.', 'La Cobertura F proporciona pagos médicos a otros que se lesionan en la propiedad del asegurado, independientemente de la culpa.', true, '2026-01-14 22:43:34.468743', '2026-01-14 22:43:34.468743') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5a414d28-6bc2-43bc-8778-c3ada7cde7d1', 'property_casualty', NULL, 'What is a loss of income endorsement for homeowners?', '¿Qué es un endoso de pérdida de ingresos para propietarios?', '["Coverage for rental income lost when a rental portion of the home is damaged", "Disability coverage", "Life insurance", "Auto coverage"]', '["Cobertura por ingresos de alquiler perdidos cuando una porción de alquiler de la casa está dañada", "Cobertura de discapacidad", "Seguro de vida", "Cobertura de auto"]', 0, 'This endorsement covers lost rental income when a portion of the insured''s home that is rented becomes uninhabitable.', 'Este endoso cubre ingresos de alquiler perdidos cuando una porción de la casa del asegurado que se alquila se vuelve inhabitable.', true, '2026-01-14 22:49:00.429761', '2026-01-14 22:49:00.429761') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5b60ce62-8391-4bf3-8f3e-06b402291370', 'property_casualty', NULL, 'What does Coverage D in a homeowners policy cover?', '¿Qué cubre la Cobertura D en una póliza de propietarios?', '["Loss of use/additional living expenses", "The dwelling", "Personal property", "Liability"]', '["Pérdida de uso/gastos de vida adicionales", "La vivienda", "Propiedad personal", "Responsabilidad"]', 0, 'Coverage D covers additional living expenses if the home becomes uninhabitable due to a covered loss.', 'La Cobertura D cubre gastos de vida adicionales si la casa se vuelve inhabitable debido a una pérdida cubierta.', true, '2026-01-14 22:43:34.457858', '2026-01-14 22:43:34.457858') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5bf839c9-bcc9-4127-ae39-cb49a731c660', 'property_casualty', NULL, 'What is personal watercraft insurance?', '¿Qué es el seguro de embarcaciones personales?', '["Coverage for jet skis and similar watercraft", "Boat insurance", "Auto insurance", "Homeowners insurance"]', '["Cobertura para motos acuáticas y embarcaciones similares", "Seguro de botes", "Seguro de auto", "Seguro de propietarios"]', 0, 'Personal watercraft insurance covers jet skis, wave runners, and similar personal watercraft.', 'El seguro de embarcaciones personales cubre motos acuáticas, wave runners y embarcaciones personales similares.', true, '2026-01-14 22:46:59.770455', '2026-01-14 22:46:59.770455') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5c0f10dc-ec57-48fd-a8bc-6dbaa8a7f52a', 'property_casualty', NULL, 'What is gap coverage?', '¿Qué es la cobertura de brecha?', '["Coverage for the difference between what you owe on a vehicle and its actual cash value", "Coverage for gaps in employment", "Medical coverage gaps", "Liability gaps"]', '["Cobertura por la diferencia entre lo que debe en un vehículo y su valor real en efectivo", "Cobertura por brechas en el empleo", "Brechas de cobertura médica", "Brechas de responsabilidad"]', 0, 'Gap coverage pays the difference between what you owe on a financed/leased vehicle and its ACV if it''s totaled.', 'La cobertura de brecha paga la diferencia entre lo que debe en un vehículo financiado/arrendado y su ACV si es pérdida total.', true, '2026-01-14 22:43:34.525114', '2026-01-14 22:43:34.525114') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5c1f84e9-021b-4b0d-8d5a-3baed413d29e', 'property_casualty', NULL, 'What is a proof of loss?', '¿Qué es una prueba de pérdida?', '["A formal sworn statement documenting the facts and amount of a loss", "The insurance policy", "The premium receipt", "A claim form"]', '["Una declaración jurada formal que documenta los hechos y el monto de una pérdida", "La póliza de seguro", "El recibo de prima", "Un formulario de reclamo"]', 0, 'A proof of loss is a formal, sworn statement submitted by the insured documenting the details and amount of a claimed loss.', 'Una prueba de pérdida es una declaración jurada formal presentada por el asegurado documentando los detalles y el monto de una pérdida reclamada.', true, '2026-01-14 22:43:34.614356', '2026-01-14 22:43:34.614356') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5e8aebe4-91c3-4a73-ad66-9fad3fa27b3c', 'property_casualty', NULL, 'What is medical payments coverage in auto insurance?', '¿Qué es la cobertura de pagos médicos en el seguro de auto?', '["Coverage for medical expenses for you and passengers regardless of fault", "Liability coverage", "Collision coverage", "Comprehensive coverage"]', '["Cobertura para gastos médicos para usted y pasajeros independientemente de la culpa", "Cobertura de responsabilidad", "Cobertura de colisión", "Cobertura comprensiva"]', 0, 'Medical payments coverage pays for medical expenses for you and your passengers injured in an auto accident, regardless of fault.', 'La cobertura de pagos médicos paga gastos médicos para usted y sus pasajeros lesionados en un accidente de auto, independientemente de la culpa.', true, '2026-01-14 22:43:34.516589', '2026-01-14 22:43:34.516589') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5ee4e3c1-56f2-44ac-9142-d6fbb62caa26', 'property_casualty', NULL, 'What is an aggregate limit?', '¿Qué es un límite agregado?', '["The maximum amount an insurer will pay for all claims during a policy period", "Per-claim limit", "Deductible amount", "Premium amount"]', '["La cantidad máxima que un asegurador pagará por todos los reclamos durante un período de póliza", "Límite por reclamo", "Monto del deducible", "Monto de la prima"]', 0, 'The aggregate limit caps the total amount the insurer will pay for all claims during the policy period.', 'El límite agregado limita la cantidad total que el asegurador pagará por todos los reclamos durante el período de la póliza.', true, '2026-01-14 22:49:00.439193', '2026-01-14 22:49:00.439193') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5fc83c43-07b0-40f7-a805-1e982569f167', 'property_casualty', NULL, 'What is identity theft coverage?', '¿Qué es la cobertura de robo de identidad?', '["Coverage for expenses related to restoring identity after identity theft", "Theft of property coverage", "Liability coverage", "Auto coverage"]', '["Cobertura para gastos relacionados con restaurar la identidad después del robo de identidad", "Cobertura de robo de propiedad", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Identity theft coverage helps pay expenses to restore your identity and credit after becoming a victim of identity theft.', 'La cobertura de robo de identidad ayuda a pagar gastos para restaurar su identidad y crédito después de ser víctima de robo de identidad.', true, '2026-01-14 22:46:59.722611', '2026-01-14 22:46:59.722611') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('60a2fd1b-c02b-4345-a71b-9c53fa41258d', 'property_casualty', NULL, 'What is the role of a claims adjuster?', '¿Cuál es el rol de un ajustador de reclamos?', '["To investigate claims and determine the amount the insurer should pay", "To sell insurance", "To underwrite policies", "To set premiums"]', '["Investigar reclamos y determinar el monto que el asegurador debe pagar", "Vender seguros", "Suscribir pólizas", "Establecer primas"]', 0, 'A claims adjuster investigates insurance claims, evaluates damages, and determines the appropriate settlement amount.', 'Un ajustador de reclamos investiga reclamos de seguro, evalúa daños y determina el monto apropiado de liquidación.', true, '2026-01-14 22:43:34.608284', '2026-01-14 22:43:34.608284') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('60a44f6f-92f2-4371-8572-3e95b7723b32', 'property_casualty', NULL, 'What is negligence in insurance terms?', '¿Qué es la negligencia en términos de seguros?', '["Failure to exercise reasonable care, resulting in harm to others", "Intentional harm", "An accident", "A covered loss"]', '["Falta de ejercer cuidado razonable, resultando en daño a otros", "Daño intencional", "Un accidente", "Una pérdida cubierta"]', 0, 'Negligence is the failure to use reasonable care, resulting in damage or injury to another person.', 'La negligencia es la falta de usar cuidado razonable, resultando en daño o lesión a otra persona.', true, '2026-01-14 18:28:35.616282', '2026-01-14 18:28:35.616282') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('641012e8-0d5c-48cc-ae7b-237700109ebf', 'property_casualty', NULL, 'What does Coverage E in a homeowners policy cover?', '¿Qué cubre la Cobertura E en una póliza de propietarios?', '["Personal liability", "The dwelling", "Personal property", "Medical payments"]', '["Responsabilidad personal", "La vivienda", "Propiedad personal", "Pagos médicos"]', 0, 'Coverage E provides personal liability protection for claims against the insured for bodily injury or property damage to others.', 'La Cobertura E proporciona protección de responsabilidad personal para reclamos contra el asegurado por lesiones corporales o daños a la propiedad de otros.', true, '2026-01-14 22:43:34.461528', '2026-01-14 22:43:34.461528') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6431ba5f-4008-4fcb-8e19-dfaba76964c8', 'property_casualty', NULL, 'What is the continuing education requirement for Texas P&C license renewal?', '¿Cuál es el requisito de educación continua para la renovación de licencia P&C de Texas?', '["24 hours including ethics", "12 hours", "40 hours", "No CE required"]', '["24 horas incluyendo ética", "12 horas", "40 horas", "No se requiere EC"]', 0, 'Texas requires 24 hours of continuing education for license renewal, including ethics hours.', 'Texas requiere 24 horas de educación continua para la renovación de licencia, incluyendo horas de ética.', true, '2026-01-14 22:43:34.393353', '2026-01-14 22:43:34.393353') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6554880c-207c-40f6-a447-4670c67bfaa9', 'property_casualty', NULL, 'What is specific coverage?', '¿Qué es la cobertura específica?', '["Coverage that lists separate limits for each item or location", "Coverage for all items together", "Liability coverage", "Auto coverage"]', '["Cobertura que lista límites separados para cada artículo o ubicación", "Cobertura para todos los artículos juntos", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Specific coverage assigns a separate coverage limit to each individual item or location.', 'La cobertura específica asigna un límite de cobertura separado a cada artículo o ubicación individual.', true, '2026-01-14 22:46:59.663197', '2026-01-14 22:46:59.663197') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('68e7019f-e126-4ce5-8735-53734d13bc3e', 'property_casualty', NULL, 'What is the National Flood Insurance Program (NFIP)?', '¿Qué es el Programa Nacional de Seguro contra Inundaciones (NFIP)?', '["A federal program providing flood insurance in participating communities", "A private insurance company", "A state program", "A type of homeowners policy"]', '["Un programa federal que proporciona seguro contra inundaciones en comunidades participantes", "Una compañía de seguros privada", "Un programa estatal", "Un tipo de póliza de propietarios"]', 0, 'The NFIP is a federal program administered by FEMA that provides flood insurance to property owners in participating communities.', 'El NFIP es un programa federal administrado por FEMA que proporciona seguro contra inundaciones a propietarios en comunidades participantes.', true, '2026-01-14 22:43:34.476026', '2026-01-14 22:43:34.476026') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('691b6625-8b91-455c-beb2-2422884bfebb', 'property_casualty', NULL, 'What is liability insurance?', '¿Qué es el seguro de responsabilidad?', '["Coverage for claims made by third parties for bodily injury or property damage", "Coverage for your own injuries", "Coverage for your own property", "Life insurance"]', '["Cobertura para reclamos hechos por terceros por lesiones corporales o daño a la propiedad", "Cobertura para tus propias lesiones", "Cobertura para tu propia propiedad", "Seguro de vida"]', 0, 'Liability insurance protects against claims resulting from injuries and damage to others for which the insured is legally responsible.', 'El seguro de responsabilidad protege contra reclamos resultantes de lesiones y daños a otros por los cuales el asegurado es legalmente responsable.', true, '2026-01-14 18:28:35.580032', '2026-01-14 18:28:35.580032') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6df541a9-306d-4611-9a93-d9266a70c726', 'property_casualty', NULL, 'What is pro rata liability?', '¿Qué es la responsabilidad prorrateada?', '["Each insurer pays its proportional share when multiple policies cover the same loss", "One insurer pays all", "No insurer pays", "The insured pays all"]', '["Cada asegurador paga su parte proporcional cuando múltiples pólizas cubren la misma pérdida", "Un asegurador paga todo", "Ningún asegurador paga", "El asegurado paga todo"]', 0, 'Pro rata liability means each insurer pays a proportion of the loss based on their policy limits relative to total coverage.', 'La responsabilidad prorrateada significa que cada asegurador paga una proporción de la pérdida basada en sus límites de póliza en relación con la cobertura total.', true, '2026-01-14 22:43:34.603024', '2026-01-14 22:43:34.603024') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('71025fef-1721-4494-8cf6-436f309bdb99', 'property_casualty', NULL, 'What is the grace period for premium payment in Texas?', '¿Cuál es el período de gracia para el pago de prima en Texas?', '["Typically 10-30 days depending on the policy", "5 days", "60 days", "90 days"]', '["Típicamente 10-30 días dependiendo de la póliza", "5 días", "60 días", "90 días"]', 0, 'The grace period allows policyholders additional time (typically 10-30 days) to pay premiums without losing coverage.', 'El período de gracia permite a los asegurados tiempo adicional (típicamente 10-30 días) para pagar primas sin perder cobertura.', true, '2026-01-14 22:43:34.670421', '2026-01-14 22:43:34.670421') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7140050a-2869-4958-828d-f75b7b8d89b2', 'property_casualty', NULL, 'What is the doctrine of reasonable expectations?', '¿Qué es la doctrina de expectativas razonables?', '["Coverage should be interpreted according to what a reasonable person would expect", "Literal interpretation only", "Insurer''s interpretation", "No interpretation needed"]', '["La cobertura debe interpretarse según lo que una persona razonable esperaría", "Solo interpretación literal", "Interpretación del asegurador", "No se necesita interpretación"]', 0, 'The doctrine of reasonable expectations means policy language is interpreted according to what the insured would reasonably expect.', 'La doctrina de expectativas razonables significa que el lenguaje de la póliza se interpreta según lo que el asegurado razonablemente esperaría.', true, '2026-01-14 22:46:59.827876', '2026-01-14 22:46:59.827876') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('71c5fa85-0c2e-45f0-8180-6f42a80c9718', 'property_casualty', NULL, 'What is a peril in insurance terms?', '¿Qué es un peligro en términos de seguros?', '["A cause of loss (fire, theft, wind, etc.)", "A coverage type", "A policy limit", "A premium"]', '["Una causa de pérdida (incendio, robo, viento, etc.)", "Un tipo de cobertura", "Un límite de póliza", "Una prima"]', 0, 'A peril is the immediate cause of loss, such as fire, theft, windstorm, or vandalism.', 'Un peligro es la causa inmediata de pérdida, como incendio, robo, tormenta de viento o vandalismo.', true, '2026-01-14 22:43:34.665075', '2026-01-14 22:43:34.665075') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('72a77cbd-4587-4b54-8477-02efedd3ff37', 'property_casualty', NULL, 'What is the concealment or fraud condition?', '¿Qué es la condición de ocultación o fraude?', '["A provision voiding coverage if the insured intentionally conceals or misrepresents material facts", "A coverage addition", "A premium discount", "A claims procedure"]', '["Una disposición que anula cobertura si el asegurado oculta o tergiversa intencionalmente hechos materiales", "Una adición de cobertura", "Un descuento de prima", "Un procedimiento de reclamos"]', 0, 'The concealment or fraud condition voids the policy if the insured intentionally hides or misrepresents material information.', 'La condición de ocultación o fraude anula la póliza si el asegurado oculta o tergiversa intencionalmente información material.', true, '2026-01-14 22:46:59.682403', '2026-01-14 22:46:59.682403') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('73b4fcf4-cb24-4c05-aabb-88f434ec7687', 'property_casualty', NULL, 'Is workers'' compensation required in Texas?', '¿Se requiere la compensación de trabajadores en Texas?', '["No, Texas is a non-compulsory state, but employers who opt out face different liability", "Yes, it is mandatory for all employers", "Only for large businesses", "Only for construction companies"]', '["No, Texas es un estado no obligatorio, pero los empleadores que no participan enfrentan diferente responsabilidad", "Sí, es obligatorio para todos los empleadores", "Solo para negocios grandes", "Solo para compañías de construcción"]', 0, 'Texas is a non-compulsory workers'' compensation state; employers can opt out but face increased liability exposure.', 'Texas es un estado de compensación de trabajadores no obligatoria; los empleadores pueden optar por no participar pero enfrentan mayor exposición a responsabilidad.', true, '2026-01-14 22:43:34.550107', '2026-01-14 22:43:34.550107') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7807fd71-923b-4196-befc-06b9b2825d05', 'property_casualty', NULL, 'What is crop insurance?', '¿Qué es el seguro de cultivos?', '["Coverage for farmers against loss of crops due to weather, disease, or price decline", "Property insurance", "Liability insurance", "Auto insurance"]', '["Cobertura para agricultores contra pérdida de cultivos debido a clima, enfermedad o disminución de precios", "Seguro de propiedad", "Seguro de responsabilidad", "Seguro de auto"]', 0, 'Crop insurance protects farmers from financial losses due to crop failure from weather, disease, or market conditions.', 'El seguro de cultivos protege a los agricultores de pérdidas financieras debido a pérdida de cultivos por clima, enfermedad o condiciones de mercado.', true, '2026-01-14 22:46:59.7877', '2026-01-14 22:46:59.7877') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('783c574f-8bbf-4335-8155-1a902cb652d6', 'property_casualty', NULL, 'What is a representation in insurance?', '¿Qué es una representación en seguros?', '["A statement made by the applicant that is substantially true", "A warranty", "A coverage limit", "A claim"]', '["Una declaración hecha por el solicitante que es sustancialmente verdadera", "Una garantía", "Un límite de cobertura", "Un reclamo"]', 0, 'A representation is a statement by the applicant that must be substantially true; only material misrepresentations void coverage.', 'Una representación es una declaración del solicitante que debe ser sustancialmente verdadera; solo tergiversaciones materiales anulan la cobertura.', true, '2026-01-14 22:46:59.812766', '2026-01-14 22:46:59.812766') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('78e70b0a-397f-4d14-92f9-e8ba5e0aec8c', 'property_casualty', NULL, 'What is the Texas Windstorm Insurance Association (TWIA)?', '¿Qué es la Asociación de Seguro contra Tormentas de Viento de Texas (TWIA)?', '["A state-created insurer providing wind and hail coverage in coastal areas", "A private insurance company", "A federal program", "A discount program"]', '["Un asegurador creado por el estado que proporciona cobertura contra viento y granizo en áreas costeras", "Una compañía de seguros privada", "Un programa federal", "Un programa de descuento"]', 0, 'TWIA provides windstorm and hail insurance for property owners in designated coastal areas of Texas.', 'TWIA proporciona seguro contra tormentas de viento y granizo para propietarios en áreas costeras designadas de Texas.', true, '2026-01-14 22:43:34.643317', '2026-01-14 22:43:34.643317') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7901195c-3727-4598-b0fc-f8134e85daa5', 'property_casualty', NULL, 'What does Coverage A in a homeowners policy cover?', '¿Qué cubre la Cobertura A en una póliza de propietarios?', '["The dwelling (main residence)", "Personal property", "Liability", "Medical payments"]', '["La vivienda (residencia principal)", "Propiedad personal", "Responsabilidad", "Pagos médicos"]', 0, 'Coverage A covers the dwelling structure itself, including attached structures like a garage.', 'La Cobertura A cubre la estructura de la vivienda en sí, incluyendo estructuras adjuntas como un garaje.', true, '2026-01-14 22:43:34.445682', '2026-01-14 22:43:34.445682') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('797ebb12-4277-4c18-838c-4185768a5019', 'property_casualty', NULL, 'What is special events insurance?', '¿Qué es el seguro de eventos especiales?', '["Short-term coverage for specific events like weddings or concerts", "Long-term coverage", "Auto coverage", "Property coverage"]', '["Cobertura a corto plazo para eventos específicos como bodas o conciertos", "Cobertura a largo plazo", "Cobertura de auto", "Cobertura de propiedad"]', 0, 'Special events insurance provides short-term coverage for liability and other risks at specific events.', 'El seguro de eventos especiales proporciona cobertura a corto plazo para responsabilidad y otros riesgos en eventos específicos.', true, '2026-01-14 22:46:59.7949', '2026-01-14 22:46:59.7949') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7a3ce5da-69f4-4203-8aec-529d66af7505', 'property_casualty', NULL, 'What is mobile home insurance?', '¿Qué es el seguro de casa móvil?', '["Coverage for manufactured homes including structure, contents, and liability", "Standard homeowners coverage", "Auto coverage", "Commercial coverage"]', '["Cobertura para casas manufacturadas incluyendo estructura, contenidos y responsabilidad", "Cobertura estándar de propietarios", "Cobertura de auto", "Cobertura comercial"]', 0, 'Mobile home insurance provides coverage similar to homeowners but designed for manufactured/mobile homes.', 'El seguro de casa móvil proporciona cobertura similar a la de propietarios pero diseñada para casas manufacturadas/móviles.', true, '2026-01-14 22:46:59.77908', '2026-01-14 22:46:59.77908') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7a5075d6-5803-4022-8a22-b136ced03b16', 'property_casualty', NULL, 'What is contribution by equal shares?', '¿Qué es la contribución por partes iguales?', '["Each insurer pays equal amounts until the loss is paid or limits are exhausted", "One insurer pays all", "Pro rata payment", "No payment"]', '["Cada asegurador paga cantidades iguales hasta que la pérdida se pague o los límites se agoten", "Un asegurador paga todo", "Pago prorrateado", "Sin pago"]', 0, 'Contribution by equal shares means each insurer pays the same amount until the loss is covered or limits are reached.', 'La contribución por partes iguales significa que cada asegurador paga la misma cantidad hasta que la pérdida se cubra o se alcancen los límites.', true, '2026-01-14 22:46:59.703739', '2026-01-14 22:46:59.703739') ON CONFLICT (id) DO NOTHING;
